533	  protected def removeSelf(x: Type) = {
534	    object remover extends Walker {
535	      override def walk(y: Any): Any = y match {
536	        case t:TraitSelfType =>
537	          if (t.getComprised.isEmpty)
538	            t.getNamed
539	          else
540	            NF.makeIntersectionType(t.getNamed, NF.makeMaybeUnionType(t.getComprised))
541	        case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
542	        case _ => super.walk(y)
543	      }
544	    }
545	    remover(x).asInstanceOf[Type]
546	  }
