548	   * For is-subtype queries, it makes no sense to stir in the comprised types;
549	   * if this is a subtype, then so are they
550	   * (unless they are declared to exclude -- but does that matter?) 
551	   */
552	  protected def removeSelfAsSubtype(x: Type) = {
