564	  private val normalizeVarTypeMemo = new scala.collection.mutable.HashMap[Id, Any]()
565	  private val normalizeTraitTypeMemo = new scala.collection.mutable.HashMap[(Id, List[StaticArg]), Any]()
566	  private val normalizeTupleTypeMemo = new scala.collection.mutable.HashMap[(List[Type], Option[Type]), Any]()
567	  private val normalizeArrowTypeMemo = new scala.collection.mutable.HashMap[(Type, Type, Effect, Boolean), Any]()
568	  private val normalizeOtherTypeMemo = new scala.collection.mutable.HashMap[Any, Any]()
569	  // The normalize memos' keys whose value was computed by reading the context: a hit on one
570	  // is a read of the context too.
571	  private val contextualNorms = new scala.collection.mutable.HashSet[Any]()
572	  private def noteNorm(k: Any): Unit = if (contextualNorms.contains(k)) traits.readContext()
573	  private def markNorm(before: Long, ks: Any*): Unit = if (traits.contextReads != before) contextualNorms ++= ks
