757	  protected def normDisjunct(xx: Iterable[Type])(implicit history: Set[hType]): List[Type] = {
758	      val x = xx.toList
759	      val result = x.foldLeft(List[Type]())((l, a) => {
760	        val l2 = l.filter(x => !isTrue(sub(x,a)))
761	        l2 ++ (if (l2.exists(x => isTrue(sub(a,x)))) Nil else List(a))
762	      })
763	      // println("normDisjunct:\n  " + x + "\n  " + result)
764	      result
765	  }
