804	   * comprises clause, as static parameters: comprises { N[\n\] } where
805	   * [\nat n\] lists N at every n. */
806	  def whereSizes(ti: ProperTraitIndex): List[StaticParam] =
807	    if (ti.comprisesTypes.isEmpty) Nil
808	    else ti.ast match {
809	      case d: TraitObjectDecl => toOption(NU.getWhereClause(d)) match {
810	        case Some(w) => toListFromImmutable(w.getBindings).filter(b =>
811	            b.getKind.isInstanceOf[KindNat] || b.getKind.isInstanceOf[KindInt]).map(b =>
812	            NF.makeStaticParam(NU.getSpan(b), null, b.getName,
813	                               _root_.java.util.Collections.emptyList[BaseType],
814	                               _root_.java.util.Collections.emptyList[BaseType],
815	                               none[Type], false, b.getKind))
816	        case None => Nil
817	      }
818	      case _ => Nil
