882	  def excludesClause(t: TraitType): Set[TraitType] = traits.memoExcludesClause(t) {
883	    val ti = typeCons(t.getName).asInstanceOf[TraitIndex]
884	    val args = toListFromImmutable(t.getArgs)
885	    val params = toListFromImmutable(ti.staticParameters)
886	    val excludes = ti match{
887	      case ti : ProperTraitIndex =>
888	        toSet(ti.excludesTypes).map(substitute(args, params, _).asInstanceOf[TraitType])
889	      case _ => Set[TraitType]()
890	    }
891	    val supers = toListFromImmutable(ti.extendsTypes).map(tw => substitute(args, params, tw.getBaseType))
892	    val transitively = supers.flatMap{
893	      case s: TraitType => excludesClause(s)
894	      case _ => Set[TraitType]()
895	    }
896	    excludes ++ transitively
897	  }
