import java.lang.classfile.*;
import java.lang.classfile.attribute.CodeAttribute;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

// java HugeScan.java <classes-dir> [limit]: lists methods whose bytecode is longer than limit (8000)
public class HugeScan {
    public static void main(String[] a) throws Exception {
        int limit = a.length > 1 ? Integer.parseInt(a[1]) : 8000;
        List<Path> files;
        try (Stream<Path> s = Files.walk(Paths.get(a[0]))) { files = s.filter(p -> p.toString().endsWith(".class")).collect(Collectors.toList()); }
        List<String> out = new ArrayList<>();
        for (Path p : files) {
            ClassModel cm = ClassFile.of().parse(Files.readAllBytes(p));
            for (MethodModel m : cm.methods()) {
                Optional<CodeAttribute> c = m.findAttribute(Attributes.code());
                if (c.isPresent() && c.get().codeLength() > limit)
                    out.add(String.format("%6d %s.%s", c.get().codeLength(), cm.thisClass().asInternalName(), m.methodName().stringValue()));
            }
        }
        Collections.sort(out, Collections.reverseOrder());
        out.forEach(System.out::println);
        System.out.println("# " + files.size() + " classes scanned, " + out.size() + " methods over " + limit);
    }
}
