import java.nio.file.*; import java.util.*;
public class Hier {
  public static void main(String[] a) throws Exception {
    List<String> names = Files.readAllLines(Paths.get(a[0]));
    Set<Class<?>> cases = new LinkedHashSet<>();
    for (String n : names) { try { cases.add(Class.forName("com.sun.fortress.nodes." + n)); } catch (Throwable t) { System.out.println("no class " + n); } }
    // a case class that is a subclass of another case class
    for (Class<?> c : cases) for (Class<?> d : cases) if (c != d && d.isAssignableFrom(c)) System.out.println("overlap: " + c.getSimpleName() + " extends " + d.getSimpleName());
    // common supertypes
    Class<?> node = Class.forName("com.sun.fortress.nodes.Node");
    for (Class<?> c : cases) if (!node.isAssignableFrom(c)) System.out.println("not a Node: " + c.getName() + " super " + c.getSuperclass().getName());
    System.out.println("cases " + cases.size());
  }
}
EOF
