    // Generate walker.  Every node class implements Node, and no two of the
    // concrete classes are related by subclassing, so a value matches at most
    // one class case, and one that is not a Node (a List, an Option, a String,
    // a Span) matches none.  The class cases are split, in their order, into
    // methods of WALKER_CASES_PER_METHOD cases each: one method holding them all
    // is longer than the 8000 bytes of bytecode above which HotSpot does not
    // compile a method (HugeMethodLimit), so it ran in the interpreter.
    writer.println();
    writer.println("trait Walker {");
    writer.println("   def apply(node:Any):Any = walk(node)");
    writer.println("   def walk(node:Any):Any = {");
    writer.println("       node match {");
    writer.println("         case n:com.sun.fortress.nodes.Node => walkNodeCases0(n)");
    writer.println("         case xs:List[_] => xs.map(walk _)");
    writer.println("         case xs:Option[_] => xs.map(walk _)");
    writer.println("         case _ => node");
    writer.println("      }");
    writer.println("   }");
    List<NodeClass> cList = mkList(ast.classes());
    Collections.reverse(cList);
    List<String> cases = new ArrayList<String>();
    for (NodeClass c : cList) {
        if (ignoreClass(c.name())) {
            continue;
        }
        if (c.isAbstract()) {
            continue;
        }

        cases.add(sub("         case S@name@fieldsNoTypes =>", "@name", c.name(), "@fieldsNoTypes", fieldsNames(c)) + "\n" +
                  sub("             S@name@fieldsNoTypes", "@name", c.name(), "@fieldsNoTypes", wrappedFieldCalls("walk", c)));
    }
    for (int m = 0; m * WALKER_CASES_PER_METHOD < cases.size() || m == 0; m++) {
        writer.println("   def walkNodeCases" + m + "(node:Any):Any = {");
        writer.println("       node match {");
        int end = Math.min(cases.size(), (m + 1) * WALKER_CASES_PER_METHOD);
        for (String c : cases.subList(m * WALKER_CASES_PER_METHOD, end)) {
            writer.println(c);
        }
        if (end < cases.size()) {
            writer.println("         case _ => walkNodeCases" + (m + 1) + "(node)");
        } else {
            writer.println("         case _ => node");
        }
        writer.println("      }");
        writer.println("   }");
    }
    writer.println("}");
}

/** The class cases in each of the walker's methods: see generateBody. */
private static final int WALKER_CASES_PER_METHOD = 30;

