import _root_.junit.framework.Assert._
import com.sun.fortress.nodes._
import com.sun.fortress.nodes_util.NodeFactory
import com.sun.fortress.scala_src.useful.TypeParser
import scala.jdk.CollectionConverters._

/* The generated walker: every method of it is short enough for the JVM to compile, a walk
 * rebuilds each node it reaches from its walked fields, and every other value comes back as it is. */
class WalkerJUTest extends TestCase {

  def typ(str: String) = TypeParser.parse(TypeParser.typ, str).get

  // HotSpot does not compile a method of more bytes of bytecode than this (HugeMethodLimit,
  // under the default DontCompileHugeMethods), so such a method always runs in the interpreter.
  val hugeMethodLimit = 8000

  def testEveryMethodCompilable() = {
    val in = classOf[Walker].getResourceAsStream("Walker.class")
    val model = try ClassFile.of().parse(in.readAllBytes()) finally in.close()
    val sizes = model.methods().asScala.toList.flatMap { m =>
      val code = m.findAttribute(Attributes.code())
      if (code.isPresent) List((m.methodName().stringValue, code.get.codeLength)) else Nil
    }
    assertTrue("Walker has methods with code", sizes.nonEmpty)
    for ((name, size) <- sizes)
      assertTrue("Walker." + name + " is " + size + " bytes of bytecode, more than " + hugeMethodLimit,
                 size <= hugeMethodLimit)
  }

  def testIdentityWalkRebuildsNodes() = {
    val w = new Walker {}
    for (s <- List("Ab[T, (Cd, D) -> Ef]", "&&{Ab, ||{Cd, Ef}}", "(Ab, i) -> BOTTOM", "ANY", "Object")) {
      val t = typ(s)
      val r = w(t)
      assertEquals(s, t, r)
      assertNotSame(s, t, r)
    }
  }

  def testOtherValuesComeBackAsTheyAre() = {
    val w = new Walker {}
    val str = "x"
    assertSame(str, w(str))
    val span = NodeFactory.typeSpan
    assertSame(span, w(span))
    val n: java.lang.Integer = 7
    assertSame(n, w(n))
    // A node class with no fields matches no case of the walker.
    val kindOp = new KindOp()
    assertSame(kindOp, w(kindOp))
    assertEquals(None, w(None))
    assertEquals(Nil, w(Nil))
    assertEquals(List(typ("Ab"), typ("T")), w(List(typ("Ab"), typ("T"))))
  }

  def testOverrideReachesNestedNodes() = {
    val zz = typ("Zz")
    val w = new Walker {
      override def walk(node: Any): Any = node match {
        case SVarType(_, id, _) if id.getText == "T" => zz
        case _ => super.walk(node)
      }
    }
    assertEquals(typ("Ab[Zz, (Cd, Zz) -> Ef]"), w(typ("Ab[T, (Cd, T) -> Ef]")))
    assertEquals(typ("&&{Zz, ||{Cd, Zz}}"), w(typ("&&{T, ||{Cd, T}}")))
    assertEquals(Some(zz), w(Some(typ("T"))))
    assertEquals(List(zz, typ("Ab[Zz]")), w(List(typ("T"), typ("Ab[T]"))))
  }
}

