# summ.py <run.txt> [n]: phase times (apis, component), the slowest top-level declarations and members
import sys, re
f = sys.argv[1]; n = int(sys.argv[2]) if len(sys.argv) > 2 else 15
times = []; decls0 = []; decls1 = []
for line in open(f, errors='replace'):
    m = re.match(r'@@TIME (\S+) (\S+) (\d+) ms', line)
    if m: times.append((m.group(1), m.group(2), int(m.group(3))))
    m = re.match(r'@@DECL (\d) (\d+) (\d+) (\S+) ?(.*)', line)
    if m:
        (decls0 if m.group(1) == '0' else decls1).append((int(m.group(2)), m.group(4), m.group(5)))
api = sum(t for u, p, t in times if u.startswith('api:'))
comp = sum(t for u, p, t in times if u.startswith('component:'))
print("apis %.1f s, component %.1f s" % (api / 1000, comp / 1000))
by = {}
for u, p, t in times:
    if t >= 1000: by[(u, p)] = by.get((u, p), 0) + t
for k, v in sorted(by.items(), key=lambda x: -x[1]): print("  %-40s %-16s %8.1f s" % (k[0], k[1], v / 1000))
if decls0:
    tot = sum(d[0] for d in decls0)
    print("top-level declarations: %d, %.1f s" % (len(decls0), tot / 1000))
    for d in sorted(decls0, reverse=True)[:n]: print("  %7.1f s  %s %s" % (d[0] / 1000, d[1], d[2]))
