    dis(for(c <- cs; d <- ds) yield and(c,d))
  case (c1: Or, c2: And) => and(c1, Or(Set(c2)))
  case _ => and(c2, c1)
}

def and(e1: EFormula, e2: EFormula)(implicit ta: TypeAnalyzer): EFormula = (e1, e2) match {
